let seed=7123;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;}const mat=(color,extra={})=>new THREE.MeshStandardMaterial({color,roughness:.86,...extra});
const palette={stone:mat('#8e9685'),sand:mat('#e4cf91'),grass:mat('#6a9665'),grassLight:mat('#9ab278'),trunk:mat('#67503a'),leaf:mat('#406f53'),leafLight:mat('#668b54'),wall:mat('#efe1ba'),wall2:mat('#cbbf98'),roof:mat('#ad6747'),roof2:mat('#c18256'),wood:mat('#60442e'),deck:mat('#b59059'),gold:mat('#c4a16c'),white:mat('#f4e5bf'),dark:mat('#243c40')};
function mesh(g,m,parent,x=0,y=0,z=0){const a=new THREE.Mesh(g,m);a.position.set(x,y,z);a.castShadow=true;a.receiveShadow=true;parent.add(a);return a;}
function box(parent,w,h,d,m,x=0,y=0,z=0){return mesh(new THREE.BoxGeometry(w,h,d),m,parent,x,y,z);}
function cylinder(parent,r1,r2,h,m,x,y,z,n=8){return mesh(new THREE.CylinderGeometry(r1,r2,h,n),m,parent,x,y,z);}
function line(parent,points,color='#4a3b2e'){const geo=new THREE.BufferGeometry().setFromPoints(points.map(p=>new THREE.Vector3(...p)));parent.add(new THREE.Line(geo,new THREE.LineBasicMaterial({color})));}

